  function thirdPersonWeaponSize(w){if(!w)return .22;if(w.id==='knife')return .17;if(w.type==='pistol')return .16;if(w.type==='smg')return .24;if(w.id==='katana')return .48;if(w.id==='baseball')return .54;if(w.type==='sniper'||w.type==='shotgun'||w.type==='rifle')return .48;if(w.type==='raygun')return .44;return .42;}
