  async function updateFpWeapon(s){if(!s)return;const fpBuild=(s.fpBuildId||0)+1;s.fpBuildId=fpBuild;if(s.fpWeapon){s.camera.remove(s.fpWeapon);s.fpWeapon=null;}const id=state().equipped[s.currentSlot];if(!id||!weaponState(id).owned)return;const w=WEAPON_MAP[id],model=await makeWeaponModel(id,fpModelSize(w));if(UI.session!==s||s.fpBuildId!==fpBuild)return;const pose=fpPose(w),g=new THREE.Group();g.add(model);g.position.copy(pose.pos);g.rotation.copy(pose.rot);g.userData.basePos=pose.pos.clone();g.userData.adsPos=pose.ads.clone();g.userData.baseRot=pose.rot.clone();if(model.userData.esklAnimations?.length){g.userData.mixer=new THREE.AnimationMixer(model);const clip=model.userData.esklAnimations.find(a=>/shoot|fire/i.test(a.name||''))||model.userData.esklAnimations[0];if(clip){g.userData.shootAction=g.userData.mixer.clipAction(clip);g.userData.shootAction.setLoop(THREE.LoopOnce,1);g.userData.shootAction.clampWhenFinished=true;}}s.camera.add(g);s.fpWeapon=g;}
