  function updateHud(s){const hpPct=clamp(s.hp/s.maxHp*100,0,100),shieldPct=s.maxShield?clamp(s.shield/s.maxShield*100,0,100):0;UI.body?.querySelector('[data-hp-bar]')?.style.setProperty('width',`${hpPct}%`);UI.body?.querySelector('[data-shield-bar]')?.style.setProperty('width',`${shieldPct}%`);const ht=UI.body?.querySelector('[data-hp-text]'),st=UI.body?.querySelector('[data-shield-text]');if(ht)ht.textContent=Math.ceil(s.hp);if(st)st.textContent=Math.ceil(s.shield);const wid=state().equipped[s.currentSlot],w=wid?weaponStats(wid):null;const wn=UI.body?.querySelector('[data-world-weapon]'),du=UI.body?.querySelector('[data-world-dura]'),am=UI.body?.querySelector('[data-world-ammo]');if(wn)wn.textContent=w?.name||'-';if(du)du.textContent=w?`${Math.round(w.durability)}% · L${w.level}`:'-';if(am)am.textContent=w?(w.type==='melee'?'NAHKAMPF':`${s.ammo[w.id]??0}/${w.mag||0}${performance.now()<s.reloadUntil?' · LÄDT…':''}`):'';const wk=UI.body?.querySelector('[data-world-kills]');if(wk)wk.textContent=fmt(state().totalKills);for(const id of ['heal','speed','shield100','shield150','shield200']){const el=UI.body?.querySelector(`[data-count="${id}"]`);if(el)el.textContent=fmt(state().inventory[id]||0);}}

  function updateLobbyPrompt(s){const p=UI.body?.querySelector('[data-world-prompt]');if(!p)return;if(s.mode!=='lobby'){p.textContent=s.view==='fps'?'V: Third Person · C Ducken · Z Liegen · SPACE Springen':'V: Ego-Perspektive · C Ducken · Z Liegen · SPACE Springen';return;}let near=null;for(const id of ['shop','online','bots']){const q=s[`place_${id}`];if(q&&Math.hypot(s.pos.x-q.x,s.pos.z-q.z)<q.radius){near=id;break;}}s.nearPlace=near;p.textContent=near==='shop'?'E · Shop öffnen':near==='online'?'E · Online-Welt betreten':near==='bots'?'E · Bot-Welt mit 10 Bots betreten':'WASD bewegen · Maus frei umsehen · SPACE springen · C ducken · Z liegen · E Teleport/Shop';}
  function interact(s){if(s.mode!=='lobby')return;if(s.nearPlace==='shop')openShop();else if(s.nearPlace==='online')startCombat('online');else if(s.nearPlace==='bots')startCombat('bots');}

  function useConsumable(s,id){const inv=state().inventory;if(!s.alive||Number(inv[id]||0)<=0)return toast('Davon hast du nichts.','bad');if(id==='heal'){if(s.hp>=100)return toast('Leben ist bereits voll.');s.hp=Math.min(100,s.hp+60);}else if(id==='speed'){s.speedBoostUntil=performance.now()+12000;}else if(id.startsWith('shield')){const value=Number(id.replace('shield',''))||100;s.maxShield=value;s.shield=value;}else return;inv[id]--;persist();updateHud(s);toast('Benutzt.','good');}

  function updateShooting(s,now){if(!s.alive||s.mode==='lobby')return;const id=state().equipped[s.currentSlot];if(!id)return;const w=weaponStats(id);if(w.durability<=0){if(UI.mouse.down&&now-s.lastShotAt>600){s.lastShotAt=now;toast(`${w.name} ist kaputt – im Shop reparieren.`,'bad');}return;}if(now<s.reloadUntil)return;if(w.type!=='melee'&&(s.ammo[id]??0)<=0){if(UI.mouse.down)beginReload(s,id);return;}if(!UI.mouse.down)return;if(now-s.lastShotAt<w.rate*1000)return;if((w.type==='pistol'||w.type==='sniper'||w.type==='shotgun')&&s.shotHeld)return;s.shotHeld=true;s.lastShotAt=now;fireWeapon(s,w);}
  function fireWeapon(s,w){const shootAction=s.fpWeapon?.userData?.shootAction;if(shootAction){shootAction.reset();shootAction.play();}if(w.type==='melee')s.meleeSwing=1;else s.weaponKick=1;if(w.type!=='melee'){s.ammo[w.id]=Math.max(0,(s.ammo[w.id]??w.mag)-1);weaponState(w.id).durability=clamp(weaponState(w.id).durability-w.durabilityLoss,0,100);}else weaponState(w.id).durability=clamp(weaponState(w.id).durability-w.durabilityLoss,0,100);persistSoon();if(w.type==='melee')return meleeAttack(s,w);const pellets=w.pellets||1;for(let i=0;i<pellets;i++)shootRay(s,w,i,pellets);muzzleFlash(s,w);}
  function shootRay(s,w,index,pellets){const spread=(100-w.stability)/100*(UI.mouse.ads?.006:.014)*(w.type==='shotgun'?3.8:1),x=(Math.random()-.5)*spread,y=(Math.random()-.5)*spread;s.raycaster||(s.raycaster=new THREE.Raycaster());s.raycaster.setFromCamera(new THREE.Vector2(x,y),s.camera);s.raycaster.far=w.range;const hits=s.raycaster.intersectObjects(s.shootables,true);for(const hit of hits){const meta=findTargetMeta(hit.object);if(hit.object.userData?.blockShot&&!meta)break;if(meta){const head=meta.zone==='head',mult=head?(w.type==='sniper'?2.05:w.type==='pistol'?1.75:1.6):1,damage=Math.max(1,Math.round(w.damage*mult));applyOutgoingHit(s,meta,damage,false,head,w.id);break;}}}
  function findTargetMeta(obj){let n=obj;while(n){if(n.userData?.esklTarget)return n.userData.esklTarget;n=n.parent;}return null;}
  function meleeAttack(s,w){const origin=s.pos.clone().add(new THREE.Vector3(0,1.15,0)),forward=forwardFromYaw(s.yaw);let best=null,dist=Infinity;for(const o of s.shootables){const meta=findTargetMeta(o);if(!meta)continue;const wp=new THREE.Vector3();o.getWorldPosition(wp);const d=origin.distanceTo(wp);if(d>w.range||d>=dist)continue;const dir=wp.clone().sub(origin).normalize();if(dir.dot(forward)<.55)continue;best=meta;dist=d;}if(best)applyOutgoingHit(s,best,50,true,false,w.id);}
  function applyOutgoingHit(s,meta,damage,ignoreShield,headshot,weaponId){if(meta.kind==='bot'){const bot=s.bots.get(meta.id);if(bot)damageBot(s,bot,damage,ignoreShield,headshot,weaponId,true);}else if(meta.kind==='remote')sendOnlineHit(s,meta.id,damage,ignoreShield,headshot,weaponId);}
  function muzzleFlash(s,w){const l=new THREE.PointLight(w.type==='raygun'?0x8b5cff:0xffd37a,w.type==='raygun'?8:3,5,.8);l.position.copy(s.camera.position);s.scene.add(l);setTimeout(()=>s.scene?.remove(l),45);}
  function beginReload(s,id=state().equipped[s.currentSlot]){const w=WEAPON_MAP[id];if(!w?.mag||performance.now()<s.reloadUntil||(s.ammo[id]??0)>=w.mag)return;s.reloadUntil=performance.now()+w.reload*1000;setTimeout(()=>{if(UI.session===s&&performance.now()+25>=s.reloadUntil){s.ammo[id]=w.mag;s.reloadUntil=0;updateHud(s);}},w.reload*1000);}

  async function createBots(s){for(let i=0;i<BOT_COUNT;i++){const gender=i%2?'woman':'man',ch=await makeCharacter(gender,`BOT ${i+1}`);if(UI.session!==s)return;const p=randomSpawn();p.x+=((i*7)%9)-4;p.z+=((i*11)%9)-4;ch.root.position.copy(p);s.scene.add(ch.root);const weapon=['glock','mini-uzi','m4','ak12','scar'][i%5];setCharacterStance(ch,'stand');const bot={id:`bot-${i}`,ch,pos:p,yaw:Math.random()*Math.PI*2,hp:100,shield:i%3===0?100:0,maxShield:i%3===0?100:0,alive:true,weapon,lastDecision:0,lastShot:0,target:null,respawnAt:0};tagTarget(ch,bot.id,'bot');s.bots.set(bot.id,bot);await attachActiveWeapon(ch,weapon);}}
